mapper.select:
select * from( SELECT d.*, u.user_name
,(st_distance (POINT (d.lng,d.lat),POINT(#{lng},#{lat}) ) *111195) AS distance
FROM sc_table_data d, tb_user u
WHERE u.user_id = d.user_id and d.status = 2 and d.is_enable =1 and d.state = 1
and d.user_id = #{userId}
and d.data_title like concat("%",#{scTableDataVo.dataTitle},"%")
and d.class_id = #{scTableDataVo.classId}
and d.status = #{scTableDataVo.status}
and d.province = #{scTableDataVo.province}
and d.city = #{scTableDataVo.city}
and d.county = #{scTableDataVo.county}
) t1 order by
t1.create_time asc,
t1.create_time desc,
t1.price_info asc,
t1.price_info desc,
t1.distance asc,
t1.distance desc,
create_time desc

SELECT d.*, u.user_name, s.class_name FROM sc_table_data d, tb_user u, sc_table_class s WHERE u.user_id = d.user_id AND d.class_id = s.class_id AND d.user_id = #{userId}
and d.class_id = #{classId}
and d.status = #{status}
order by d.create_time desc

SELECT d.*, u.user_name
,if((select count(0) from sc_follow c where c.user_id = #{userId} and type =1 and c.data_id = #{dataId})>0,1,0) as isFollow
FROM sc_table_data d, tb_user u WHERE u.user_id = d.user_id and d.data_id = #{dataId}

        SELECT d.*,
        u.user_name
        FROM sc_table_data d,
        tb_user u
        WHERE u.user_id = d.user_id
        
            and d.user_id = #{scTableDataVo.userId}
        
        
            and d.data_title like concat("%",#{scTableDataVo.dataTitle},"%")
        
        
            and d.class_id = #{scTableDataVo.classId}
        
        
            and u.user_name like concat("%",#{scTableDataVo.userName},"%")
        
        
            and d.status = #{scTableDataVo.status}
        
        
            and u.phone like concat("%",#{scTableDataVo.phone},"%")
        
        
            and d.province = #{scTableDataVo.province}
        
        
            and d.city like concat("%",#{scTableDataVo.city},"%")
        
        
            and d.county = #{scTableDataVo.county}
        
        
            
                order by create_time desc
            
            
                order by d.browse_count DESC
